<?php
namespace Tests\Feature;
use App\Models\Instansi;use App\Models\KategoriInstansi;use App\Models\Pembinaan;use App\Models\PembinaanFile;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class PembinaanFileUiFeatureTest extends TestCase { use RefreshDatabase;
 private function item(User $u): Pembinaan {$c=KategoriInstansi::create(['nama'=>'UI Cat '.$u->id,'status_aktif'=>true]);$i=Instansi::create(['kategori_instansi_id'=>$c->id,'nama'=>'UI Inst '.$u->id,'status_aktif'=>true]);return Pembinaan::create(['instansi_id'=>$i->id,'created_by'=>$u->id,'tanggal_mulai'=>'2026-10-01','metode_pelaksanaan'=>'Daring','layanan'=>'UI Service','status_dokumen'=>'Tahap Persiapan']);}
 public function test_detail_lists_related_file_and_upload_form(): void {Storage::fake('local');$u=User::factory()->role('admin')->create();$p=$this->item($u);$file=UploadedFile::fake()->createWithContent('laporan.pdf','%PDF test');$this->actingAs($u)->post('/pembinaan/'.$p->id.'/files',['file'=>$file,'jenis'=>'laporan','visibilitas'=>'Private']);$this->actingAs($u)->get('/pembinaan/'.$p->id)->assertOk()->assertSee('laporan.pdf')->assertSee('Upload file')->assertSee(route('pembinaan.files.download',PembinaanFile::first()));}
 public function test_empty_detail_shows_empty_state_and_foreign_file_not_shown(): void {$u=User::factory()->role('monitoring')->create();$v=User::factory()->role('pelaksana')->create();$own=$this->item($u);$foreign=$this->item($v);PembinaanFile::create(['pembinaan_id'=>$foreign->id,'uploaded_by'=>$v->id,'jenis'=>'materi','nama_asli'=>'foreign.pdf','path'=>'missing','mime_type'=>'application/pdf','ukuran'=>1,'visibilitas'=>'Private']);$this->actingAs($u)->get('/pembinaan/'.$own->id)->assertSee('Belum ada file.')->assertDontSee('foreign.pdf')->assertDontSee('Upload file');}
}
